pub fn resume(c: &mut Cpu, a: u32) {
    let i = RANGES.partition_point(|r| r.0 <= a);
    match i.checked_sub(1).map(|k| RANGES[k]) {
        Some((s, e, f)) if a < e => { if a == s { dispatch(c, a) } else { f(c, a) } }
        _ => dispatch(c, a),
    }
}
